<script setup>
import {computed,ref} from 'vue';
const imageErrors=ref({});
import BalanceActivity from './BalanceActivity.vue';
const props=defineProps({lesson:{type:Object,required:true},progress:{type:Object,default:()=>({})},preview:Boolean});
const emit=defineEmits(['progress']);
const kinds={explanation:'讲解',example:'例题',activity:'互动',practice:'随堂练习',check:'独立检查'};
function update(block,patch){emit('progress',block.id,{...props.progress[block.id],...patch})}
const questions=computed(()=>props.lesson.questions||[]);
</script>
<template><article class="curriculum-reading"><div class="curriculum-reading-intro"><Status v-if="preview">学生预览</Status><h2>{{ lesson.title }}</h2><p>{{ lesson.goal }}</p></div><section v-for="(block,index) in lesson.blocks||[]" :key="block.id" class="curriculum-block" :data-block="block.id"><div class="curriculum-block-heading"><span>{{ String(index+1).padStart(2,'0') }}</span><h3>{{ block.title }}</h3><Status>{{ kinds[block.type]||'历史内容' }}</Status></div><p class="preserve-lines curriculum-prose">{{ block.content }}</p><figure v-if="block.imageUrl" class="curriculum-figure"><p v-if="imageErrors[block.id]" role="alert" class="form-error">图片无法读取<Button variant="ghost" @click="imageErrors[block.id]=false">重试图片</Button></p><img v-else :src="block.imageUrl+'?inline=1'" :alt="block.imageAlt||block.title" @error="imageErrors[block.id]=true"/></figure><BalanceActivity v-if="block.type==='activity'&&block.activity?.type==='balance'" :config="block.activity" :model-value="progress[block.id]?.weight||0" @update:model-value="update(block,{weight:$event,completed:false})"/><p v-else-if="block.type==='activity'" class="form-error">该互动暂不支持，请联系教师。</p><template v-if="block.type==='activity'"><label :for="'explain-'+block.id" class="field-label">用自己的话解释观察结果</label><Textarea :id="'explain-'+block.id" :model-value="progress[block.id]?.explanation||''" @update:model-value="update(block,{explanation:$event,completed:false})"/></template><template v-if="['practice','check'].includes(block.type)"><div v-for="q in questions.filter(q=>block.questionIds?.includes(q.id))" :key="q.id" class="curriculum-question-preview"><strong>{{ q.prompt }}</strong><p class="math-equation">{{ q.equation }}</p><slot name="question" :question="q" :index="questions.findIndex(item=>item.id===q.id)" :block="block"><p v-if="preview" class="model-model-name">{{ block.type==='practice'?'随堂作答区':'独立作答区' }}</p></slot></div></template><Button v-else variant="outline" size="sm" :disabled="block.type==='activity'&&(!(progress[block.id]?.weight>0)||!progress[block.id]?.explanation?.trim())" @click="update(block,{completed:!progress[block.id]?.completed})">{{ progress[block.id]?.completed?'已完成':'标记完成' }}</Button></section></article></template>
